//! Resumable security/federation workflow fabric for Worldgen P20.
use super::security_federation_copilot_support::{self, SecurityFederationCopilotReceipt, SecurityFederationCopilotRequest};
use bioprism_foundation::{PRECLINICAL_BOUNDARY, RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize, Serialize};
use serde_json::json;
use std::collections::BTreeSet;
use thiserror::Error;
pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.security-federation-workflow-receipt+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct SecurityFederationWorkflowRequest{pub workflow_id:String,pub copilot:SecurityFederationCopilotRequest,pub stage_order:Vec<String>,pub completed_stage_order:Vec<String>,pub checkpoint_seq:u64,pub budget_units:u64,pub compensation_enabled:bool,pub replay_identity:ContentHash}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct SecurityFederationWorkflowReceipt{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub workflow_id:String,pub disposition:String,pub stage_order:Vec<String>,pub completed_stage_order:Vec<String>,pub pending_stage_order:Vec<String>,pub compensation_order:Vec<String>,pub checkpoint_seq:u64,pub budget_units:u64,pub consumed_units:u64,pub replay_identity:ContentHash,pub copilot:SecurityFederationCopilotReceipt,pub workflow_digest:ContentHash,pub artifact:serde_json::Value,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum SecurityFederationWorkflowError{#[error("invalid security/federation workflow request: {0}")]Invalid(String),#[error("invalid security/federation workflow receipt: {0}")]Receipt(String),#[error("security/federation workflow artifact failed: {0}")]Artifact(String)}
fn hash(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn ordered(v:&[String])->bool{v.windows(2).all(|w|w[0]<w[1])}
impl SecurityFederationWorkflowReceipt{pub fn validate(&self)->Result<(),SecurityFederationWorkflowError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.get("boundary").and_then(|v|v.as_str())!=Some(PRECLINICAL_BOUNDARY)||self.artifact.get("content_type").and_then(|v|v.as_str())!=Some(CONTENT_TYPE)||!self.raw_data_local||!self.aggregate_only||self.workflow_id.trim().is_empty()||self.stage_order.is_empty()||self.checkpoint_seq==0||self.budget_units==0||self.consumed_units>self.budget_units||![&self.replay_identity,&self.workflow_digest].into_iter().all(hash)||self.artifact.get("content_hash").and_then(|v|v.as_str())!=Some(self.workflow_digest.as_str()){return Err(SecurityFederationWorkflowError::Receipt("security workflow identity, budget, locality, or digest is incomplete".into()))}for v in [&self.stage_order,&self.completed_stage_order,&self.pending_stage_order,&self.compensation_order,&self.effect_receipts]{if !ordered(v){return Err(SecurityFederationWorkflowError::Receipt("security workflow vectors are not canonical".into()))}}let ids=self.stage_order.iter().cloned().collect::<BTreeSet<_>>();let p=self.completed_stage_order.iter().chain(&self.pending_stage_order).cloned().collect::<BTreeSet<_>>();if ids!=p{return Err(SecurityFederationWorkflowError::Receipt("security workflow stages do not partition".into()))}Ok(())}}
pub fn manifest(feature_id:&str,version:&str,scale:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":version,"owner_crate":"worldgen","consumers":["security steward","federation operator","research program lead"],"behavior":format!("orchestrate resumable security/federation admission for {scale}"),"value":"makes cross-site export qualification restartable, budgeted, compensating, and replayable","input_schema":"SecurityFederationWorkflowRequest1@1","output_schema":"SecurityFederationWorkflowReceipt1@1","effects":["schedule:signed-federation-workflow","block:unsafe-export"],"permissions":["schedule:bounded-federation-workflow"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":PRECLINICAL_BOUNDARY})}
pub fn schedule(r:&SecurityFederationWorkflowRequest,feature_id:&str,version:&str,scale:&str,require_approval:bool,require_federation:bool)->Result<SecurityFederationWorkflowReceipt,SecurityFederationWorkflowError>{if r.workflow_id.trim().is_empty()||r.stage_order.is_empty()||r.stage_order!={let mut x=r.stage_order.clone();x.sort();x.dedup();x}||r.checkpoint_seq==0||r.budget_units==0||!r.compensation_enabled||!hash(&r.replay_identity)||r.copilot.security_request.replay_identity!=r.replay_identity{return Err(SecurityFederationWorkflowError::Invalid("security workflow request is invalid".into()))}let completed=r.completed_stage_order.iter().cloned().collect::<BTreeSet<_>>();if completed.iter().any(|x|!r.stage_order.contains(x)){return Err(SecurityFederationWorkflowError::Invalid("security workflow completed stage is undeclared".into()))}let copilot=security_federation_copilot_support::run(&r.copilot,feature_id,version,scale,require_approval,require_federation).map_err(|e|SecurityFederationWorkflowError::Invalid(e.to_string()))?;let pending=r.stage_order.iter().filter(|x|!completed.contains(*x)).cloned().collect::<Vec<_>>();let consumed=(r.copilot.action_order.len()as u64).min(r.budget_units);let compensation=if copilot.disposition=="blocked"{vec![format!("workflow:{}:retain-security-verdict",r.workflow_id)]}else{Vec::new()};let disposition=if copilot.disposition=="blocked"{"blocked"}else if pending.is_empty(){"admitted"}else{"partial"};let effects=if disposition=="admitted"{vec![format!("schedule:signed-federation-workflow:{}",r.workflow_id)]}else{vec!["block:unsafe-export".into()]};let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":feature_id,"workflow_id":r.workflow_id,"disposition":disposition,"stage_order":r.stage_order,"completed_stage_order":completed,"pending_stage_order":pending,"compensation_order":compensation,"checkpoint_seq":r.checkpoint_seq,"budget_units":r.budget_units,"consumed_units":consumed,"replay_identity":r.replay_identity,"copilot":copilot.clone(),"workflow_digest":null,"effect_receipts":effects,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let d=ContentHash::of_value(&payload).map_err(|e|SecurityFederationWorkflowError::Artifact(e.to_string()))?;let strings=|k:&str|payload[k].as_array().map(|a|a.iter().filter_map(|v|v.as_str().map(String::from)).collect()).unwrap_or_default();let out=SecurityFederationWorkflowReceipt{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:version.into(),feature_id:feature_id.into(),workflow_id:r.workflow_id.clone(),disposition:disposition.into(),stage_order:r.stage_order.clone(),completed_stage_order:completed.iter().cloned().collect(),pending_stage_order:strings("pending_stage_order"),compensation_order:strings("compensation_order"),checkpoint_seq:r.checkpoint_seq,budget_units:r.budget_units,consumed_units:consumed,replay_identity:r.replay_identity.clone(),copilot,workflow_digest:d.clone(),artifact:json!({"content_type":CONTENT_TYPE,"content_hash":d,"boundary":PRECLINICAL_BOUNDARY}),effect_receipts:strings("effect_receipts"),raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};out.validate()?;Ok(out)}
